function prompt {
    $ESC = [char]27
    "PS $ESC[38;5;82m$($ExecutionContext.SessionState.Path.CurrentLocation)$('>' * ($nestedPromptLevel + 1)) $ESC[0m"
}

function dir {
    $ESC = [char]27
    # Runs the directory search, turns it into text strings, and forces neon hacker green line-by-line
    Get-ChildItem @args | Out-String -Stream | ForEach-Object {
        if ($_ -match '\S') {
            # Apply hacker green [38;5;82m to the line text
            "$ESC[38;5;82m$_$ESC[0m"
        } else {
            $_
        }
    }
}


# Import the Chocolatey Profile that contains the necessary code to enable
# tab-completions to function for `choco`.
# Be aware that if you are missing these lines from your profile, tab completion
# for `choco` will not function.
# See https://ch0.co/tab-completion for details.
$ChocolateyProfile = "$env:ChocolateyInstall\helpers\chocolateyProfile.psm1"
if (Test-Path($ChocolateyProfile)) {
  Import-Module "$ChocolateyProfile"
}

